import { GitHub } from '@mui/icons-material';
import {
  Alert,
  AlertTitle,
  Box,
  Button,
  Chip,
  Divider,
  Snackbar,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import React, { useState } from 'react';

const ProjectMetadata = ({ project }: { project: any }) => {
  const [copyOpen, setCopyOpen] = useState(false);

  const onCopyLink = async (link: string) => {
    setCopyOpen(true);
    if (navigator.clipboard) {
      await navigator.clipboard.writeText(link);
    }
  };

  return (
    <>
      <Box sx={{ height: '100%', bgcolor: 'rgba(100,100,100,0.1)' }}>
        <Stack
          sx={{
            pt: 3,
            pb: 8,
            px: 2,

            height: 'calc(100vh - 65px)',
          }}
          gap="1rem"
          color="white"
          justifyContent={'space-between'}
        >
          <Box>
            <Box sx={{ p: 2 }}>
              <Typography>
                <strong>Completed</strong>
              </Typography>
              <Divider sx={{ my: 1 }} />
              <Typography>{project.Completed}</Typography>
              {/* <Typography>{project.dateCompleted}</Typography> */}
            </Box>
            {project.RepoLink && (
              <Box
                sx={{ p: 2, cursor: 'pointer' }}
                onClick={() => onCopyLink(project.RepoLink)}
              >
                <Typography>
                  <strong>Repository</strong>
                </Typography>
                <Divider sx={{ my: 1 }} />
                <TextField
                  disabled
                  sx={{
                    mt: 1,
                    fontSize: '0.25rem',
                    backgroundColor: 'rgba(90,90,90,0.1)',
                    p: 0,
                    cursor: 'pointer',
                  }}
                  type="text"
                  InputProps={{
                    startAdornment: <GitHub sx={{ mr: 2 }} />,
                    style: { cursor: 'pointer', fontSize: '12px' },
                  }}
                  fullWidth
                  placeholder={project.RepoLink}
                />
                <Box
                  sx={{
                    display: 'flex',
                    justifyContent: 'flex-end',
                    pt: 0.5,
                    pr: 0.5,
                  }}
                >
                  <Typography
                    variant="caption"
                    sx={{
                      textAlign: 'right',
                      fontWeight: 600,
                      color: copyOpen ? 'success.main' : 'inherit',
                    }}
                  >
                    {copyOpen ? 'Copied!' : 'Click to Copy'}
                  </Typography>
                </Box>{' '}
              </Box>
            )}

            <Box sx={{ p: 2 }}>
              <Typography>
                {' '}
                <strong>Tools</strong>
              </Typography>
              <Divider sx={{ mt: 1, mb: 2 }} />
              <Box sx={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                {project.skills.map((s) => (
                  <Chip
                    label={s.skill.SkillName}
                    variant="filled"
                    sx={{
                      bgcolor: `var(--${s.SkillCategory})`,
                      color: 'white',
                      fontWeight: 800,
                    }}
                  />
                ))}
              </Box>
            </Box>
          </Box>
          <Box sx={{ p: 2 }}>
            <Divider sx={{ mb: 3 }} />
            <a href={project.LiveLink} target="_blank">
              <Button fullWidth variant="contained">
                See It Live
              </Button>
            </a>
          </Box>
        </Stack>
      </Box>
      <Snackbar
        open={copyOpen}
        autoHideDuration={6000}
        onClose={() => setCopyOpen(false)}
        // TransitionProps={{ onExited: handleExited }}
      >
        <Alert severity="success" variant="filled" sx={{ color: 'white' }}>
          <AlertTitle>Copied to Clipboard!</AlertTitle>
        </Alert>
      </Snackbar>
    </>
  );
};

export default ProjectMetadata;
