import React, { useContext } from 'react';
import styled from '@emotion/styled';
import { Box } from '@mui/system';
import { Chip, Divider, Typography } from '@mui/material';
import { GatsbyImage, getImage } from 'gatsby-plugin-image';
import { TheAppContext } from '../../provider/AppContext';
import ProjectCarousel from './ProjectCarousel';
const Styled__Wrap = styled(Box)`
  display: flex;
  flex-direction: column;
  justify-content: center;
`;

const Styled__Project = styled(Box)`
  max-width: 400px;
  margin: auto;
  color: white;
  background-color: ${({ theme }) => theme.palette.background.paper};
  padding: 1rem;
  border-radius: 6px;
  && img.cover {
    border-radius: 6px;
    max-width: calc(400px - 2rem);
  }
`;

const Styled__Carousel = styled(Box)`
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 0.5rem;
`;

const Description__Box = styled(Box)`
  && ul {
    padding-bottom: 0;
  }
  && li {
    margin-left: 2rem;
  }
`;
const SingleProjectDetail = ({ project }) => {
  const { setBoxShowing } = useContext(TheAppContext);
  return (
    <Styled__Wrap>
      <Styled__Project>
        <Box sx={{ width: '100%' }}>
          {project.Cover.ext === '.png' ? (
            <GatsbyImage
              image={getImage(project.Cover.localFile)}
              alt={project.Cover.alternativeText}
              style={{ height: 'auto', width: '100%' }}
            />
          ) : (
            <img className="cover" src={project.Cover.localFile.url} />
          )}
        </Box>
        {project?.Gallery?.length > 0 && (
          <Styled__Carousel>
            {project.Gallery.map((pic, index) => (
              <Box
                key={index}
                sx={{ cursor: 'pointer' }}
                onClick={() =>
                  setBoxShowing({
                    visible: true,
                    component: <ProjectCarousel imgArray={project.Gallery} />,
                  })
                }
              >
                <GatsbyImage
                  image={getImage(pic.localFile)}
                  alt="test"
                  style={{
                    width: '60px',
                    height: '60px',
                    display: 'block',
                  }}
                />
              </Box>
            ))}
          </Styled__Carousel>
        )}

        <Typography sx={{ my: 2 }} variant="h5">
          {project.Title}
        </Typography>
        <Divider sx={{ my: 2 }} />

        <Box sx={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
          {project.tags
            .flatMap((t) => t.tagName)
            .map((t) => (
              <Chip
                label={t}
                variant="filled"
                color="info"
                sx={{ color: 'white' }}
              />
            ))}
        </Box>
        <Divider sx={{ my: 2 }} />
        <Description__Box
          dangerouslySetInnerHTML={{
            __html: project?.Narrative?.data?.childMarkdownRemark?.html,
          }}
        ></Description__Box>
      </Styled__Project>
    </Styled__Wrap>
  );
};

export default SingleProjectDetail;
